import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface NewsItem {
  id: string;
  title: string;
  excerpt: string;
  author: string;
  date: string;
  category: 'AI' | 'Dev' | 'Tech' | 'Hardware';
  imageUrl: string;
  content?: string;
}

export interface ResourceItem {
  id: string;
  title: string;
  description: string;
  type: 'Tutorial' | 'Guide' | 'Documentation' | 'Course';
  difficulty: 'Beginner' | 'Intermediate' | 'Advanced';
  tags: string[];
  link: string;
}

export interface ChatMessage {
  role: 'user' | 'assistant';
  content: string;
}

import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const getLatestTechBriefing = async () => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: "Genera un resumen breve de las 3 tendencias más importantes en tecnología y IA de hoy en español. Usa un tono profesional para desarrolladores.",
      config: {
        tools: [{ googleSearch: {} }]
      }
    });
    return response.text;
  } catch (error) {
    console.error("Error fetching briefing:", error);
    return "Error al obtener el briefing diario. Inténtalo más tarde.";
  }
};

export const askDevAssistant = async (prompt: string, history: { role: string, content: string }[]) => {
  try {
    const chat = ai.chats.create({
      model: "gemini-3-flash-preview",
      config: {
        systemInstruction: "Eres un asistente experto en programación, desarrollo de software y IA. Respondes de forma clara, técnica y útil. Usa bloques de código si es necesario."
      }
    });

    // In a real scenario, you'd feed the history back into the chat session.
    // For this simplified version, we just send the current prompt.
    const response = await chat.sendMessage({ message: prompt });
    return response.text;
  } catch (error) {
    console.error("Error in DevAssistant:", error);
    return "Lo siento, tuve un problema procesando tu consulta.";
  }
};

