import React from 'react';
import { NewsItem } from '../types';

interface NewsCardProps {
  news: NewsItem;
}

const NewsCard: React.FC<NewsCardProps> = ({ news }) => {
  const getCategoryColor = (category: string) => {
    switch (category) {
      case 'AI': return 'bg-purple-900/30 text-purple-400 border-purple-800/50';
      case 'Dev': return 'bg-blue-900/30 text-blue-400 border-blue-800/50';
      case 'Tech': return 'bg-green-900/30 text-green-400 border-green-800/50';
      default: return 'bg-slate-800 text-slate-400 border-slate-700';
    }
  };

  return (
    <div className="group bg-[#161b22] border border-[#30363d] rounded-lg overflow-hidden hover:border-[#8b949e] transition-all flex flex-col h-full">
      <div className="h-48 overflow-hidden relative">
        <img 
          src={news.imageUrl} 
          alt={news.title} 
          className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105"
        />
        <div className="absolute top-3 left-3">
          <span className={`text-[10px] font-bold px-2 py-1 rounded border uppercase ${getCategoryColor(news.category)}`}>
            {news.category}
          </span>
        </div>
      </div>
      <div className="p-5 flex flex-col flex-grow">
        <h3 className="text-lg font-bold text-slate-100 group-hover:text-blue-400 transition-colors leading-tight mb-2">
          {news.title}
        </h3>
        <p className="text-sm text-slate-400 line-clamp-3 mb-4 flex-grow">
          {news.excerpt}
        </p>
        <div className="flex items-center justify-between mt-auto pt-4 border-t border-[#30363d]">
          <span className="text-xs text-slate-500 font-medium">Por {news.author}</span>
          <span className="text-xs text-slate-500">{news.date}</span>
        </div>
      </div>
    </div>
  );
};

