    { role: 'assistant', content: '¡Hola! Soy DevPulse AI. ¿En qué puedo ayudarte hoy con tu código o dudas tecnológicas?' }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMsg: ChatMessage = { role: 'user', content: input };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsLoading(true);

    const response = await askDevAssistant(input, messages);

    setMessages(prev => [...prev, { role: 'assistant', content: response || 'Sin respuesta.' }]);
    setIsLoading(false);
  };

  return (
    <div className="max-w-4xl mx-auto px-4 sm:px-6 py-12 flex flex-col h-[calc(100vh-8rem)]">
      <div className="flex-shrink-0 mb-6 text-center">
        <h1 className="text-3xl font-bold text-white mb-2">DevPulse AI Assistant</h1>
        <p className="text-slate-400">Pregunta sobre frameworks, debugging o tendencias tecnológicas.</p>
      </div>

      <div 
        ref={scrollRef}
        className="flex-grow overflow-y-auto bg-[#0d1117] border border-[#30363d] rounded-t-xl p-4 space-y-4 scroll-smooth"
      >
        {messages.map((msg, idx) => (
          <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] rounded-2xl p-4 ${
              msg.role === 'user' 
                ? 'bg-blue-600 text-white rounded-tr-none' 
                : 'bg-[#161b22] text-slate-200 border border-[#30363d] rounded-tl-none'
            }`}>
              <div className="text-sm whitespace-pre-wrap">
                {msg.content}
              </div>
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex justify-start">
            <div className="bg-[#161b22] border border-[#30363d] rounded-2xl rounded-tl-none p-4">
              <div className="flex space-x-2">
                <div className="w-2 h-2 bg-slate-500 rounded-full animate-bounce" style={{ animationDelay: '0s' }}></div>
                <div className="w-2 h-2 bg-slate-500 rounded-full animate-bounce" style={{ animationDelay: '0.2s' }}></div>
                <div className="w-2 h-2 bg-slate-500 rounded-full animate-bounce" style={{ animationDelay: '0.4s' }}></div>
              </div>
            </div>
          </div>
        )}
      </div>

      <div className="flex-shrink-0 bg-[#161b22] border-x border-b border-[#30363d] rounded-b-xl p-4">
        <div className="relative flex items-center">
          <input 
            type="text" 
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && handleSend()}
            placeholder="Escribe tu duda técnica aquí..."
            className="w-full bg-[#010409] border border-[#30363d] rounded-lg py-3 px-4 pr-12 text-slate-200 focus:outline-none focus:ring-1 focus:ring-blue-500 transition-all"
          />
          <button 
            onClick={handleSend}
            disabled={isLoading || !input.trim()}
            className="absolute right-2 p-2 text-blue-500 hover:text-blue-400 disabled:text-slate-600 transition-colors"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" />
            </svg>
          </button>
        </div>
        <p className="text-[10px] text-slate-500 mt-2 text-center font-mono">
          Powered by Gemini 3.0 Flash Preview
        </p>
      </div>
    </div>
  );
};

