const ITEMS_PER_PAGE = 4;

const Resources: React.FC = () => {
  const [activeType, setActiveType] = useState<string>('Todos');
  const [activeDiff, setActiveDiff] = useState<string>('Todos');
  const [currentPage, setCurrentPage] = useState(1);

  // Filter logic
  const filteredResources = useMemo(() => {
    return RESOURCES_LIST.filter(res => {
      const matchesType = activeType === 'Todos' || res.type === activeType;
      const matchesDiff = activeDiff === 'Todos' || 
        (activeDiff === 'Principiante' && res.difficulty === 'Beginner') ||
        (activeDiff === 'Intermedio' && res.difficulty === 'Intermediate') ||
        (activeDiff === 'Avanzado' && res.difficulty === 'Advanced');
      return matchesType && matchesDiff;
    });
  }, [activeType, activeDiff]);

  // Pagination logic
  const totalPages = Math.ceil(filteredResources.length / ITEMS_PER_PAGE);
  const startIndex = (currentPage - 1) * ITEMS_PER_PAGE;
  const paginatedResources = filteredResources.slice(startIndex, startIndex + ITEMS_PER_PAGE);

  const handleRipple = (e: React.MouseEvent<HTMLButtonElement>) => {
    (window as any).createRipple?.(e);
  };

  const handlePageChange = (e: React.MouseEvent<HTMLButtonElement>, page: number) => {
    handleRipple(e);
    setCurrentPage(page);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const resetAndFilter = (e: React.MouseEvent<HTMLButtonElement>, type: string, isDiff: boolean = false) => {
    handleRipple(e);
    if (isDiff) setActiveDiff(type);
    else setActiveType(type);
    setCurrentPage(1);
  };

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12">
      <div className="mb-12">
        <h1 className="text-4xl font-bold text-white mb-4">Centro de Recursos</h1>
        <p className="text-slate-400 mb-8 max-w-2xl">Colección curada de tutoriales, guías técnicas y cursos gratuitos para potenciar tu carrera profesional.</p>

        <div className="grid grid-cols-1 md:grid-cols-4 gap-8">
          <div className="md:col-span-1 space-y-8">
            <div>
              <h3 className="text-xs font-bold text-slate-500 uppercase tracking-widest mb-4">Filtrar por Tipo</h3>
              <ul className="space-y-2">
                {['Todos', 'Tutorial', 'Guide', 'Documentation', 'Course'].map(type => (
                  <li key={type}>
                    <button 
                      onClick={(e) => resetAndFilter(e, type)}
                      className={`ripple-container text-sm transition-colors py-1 px-2 rounded-md ${
                        activeType === type ? 'text-blue-500 font-bold bg-blue-500/10' : 'text-slate-400 hover:text-blue-400'
                      }`}
                    >
                      {type === 'Guide' ? 'Guías' : type === 'Course' ? 'Cursos' : type === 'Documentation' ? 'Documentación' : type}
                    </button>
                  </li>
                ))}
              </ul>
            </div>
            <div>
              <h3 className="text-xs font-bold text-slate-500 uppercase tracking-widest mb-4">Dificultad</h3>
              <ul className="space-y-2">
                {['Todos', 'Principiante', 'Intermedio', 'Avanzado'].map(diff => (
                  <li key={diff}>
                    <button 
                      onClick={(e) => resetAndFilter(e, diff, true)}
                      className={`ripple-container text-sm transition-colors py-1 px-2 rounded-md ${
                        activeDiff === diff ? 'text-blue-500 font-bold bg-blue-500/10' : 'text-slate-400 hover:text-blue-400'
                      }`}
                    >
                      {diff}
                    </button>
                  </li>
                ))}
              </ul>
            </div>
          </div>

          <div className="md:col-span-3 flex flex-col">
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 mb-10">
              {paginatedResources.length > 0 ? (
                paginatedResources.map(res => (
                  <ResourceCard key={res.id} resource={res} />
                ))
              ) : (
                <div className="col-span-full py-20 text-center border border-dashed border-slate-700 rounded-lg">
                   <p className="text-slate-500 italic">No se encontraron recursos que coincidan con tus filtros.</p>
                </div>
              )}
            </div>

            {/* Pagination Controls */}
            {totalPages > 1 && (
              <div className="flex items-center justify-center space-x-2 mt-auto py-4 border-t border-[#30363d]">
                <button
                  onClick={(e) => handlePageChange(e, Math.max(1, currentPage - 1))}
                  disabled={currentPage === 1}
                  className="ripple-container px-3 py-1.5 rounded-md text-sm font-medium transition-colors bg-[#161b22] border border-[#30363d] text-slate-400 hover:text-white disabled:opacity-30 disabled:cursor-not-allowed"
                >
                  Anterior
                </button>

                <div className="flex space-x-1">
                  {Array.from({ length: totalPages }, (_, i) => i + 1).map(page => (
                    <button
                      key={page}
                      onClick={(e) => handlePageChange(e, page)}
                      className={`ripple-container w-10 h-10 rounded-md text-sm font-medium transition-all ${
                        currentPage === page
                          ? 'bg-blue-600 text-white border-blue-500'
                          : 'bg-[#0d1117] text-slate-400 border border-[#30363d] hover:border-slate-500'
                      }`}
                    >
                      {page}
                    </button>
                  ))}
                </div>

                <button
                  onClick={(e) => handlePageChange(e, Math.min(totalPages, currentPage + 1))}
                  disabled={currentPage === totalPages}
                  className="ripple-container px-3 py-1.5 rounded-md text-sm font-medium transition-colors bg-[#161b22] border border-[#30363d] text-slate-400 hover:text-white disabled:opacity-30 disabled:cursor-not-allowed"
                >
                  Siguiente
                </button>
              </div>
            )}

            <div className="mt-4 text-center text-xs text-slate-500">
              Mostrando {startIndex + 1}-{Math.min(startIndex + ITEMS_PER_PAGE, filteredResources.length)} de {filteredResources.length} recursos
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

