              {isLogin && <a href="#" className="text-[10px] text-blue-500 hover:underline">¿Olvidaste tu clave?</a>}
            </div>
            <input 
              type="password" 
              required
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="••••••••"
              className="w-full bg-[#0d1117] border border-[#30363d] rounded-lg py-2.5 px-4 text-slate-200 focus:outline-none focus:ring-1 focus:ring-blue-500 transition-all text-sm"
