                )}
              </div>
            ) : (
              <Link 
                to="/login"
                className="bg-slate-800 hover:bg-slate-700 text-white text-xs font-semibold py-1.5 px-4 rounded-md border border-slate-600 transition-all"
              >
                Acceso
              </Link>
            )}
          </div>
        </div>
      </div>
    </nav>
  );
};

