import React, { useState, useEffect, useMemo } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import Logo from '../components/Logo';

const Auth: React.FC = () => {
  const [isLogin, setIsLogin] = useState(true);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [showPasswordRequirements, setShowPasswordRequirements] = useState(false);
  const navigate = useNavigate();
  const location = useLocation();

  // Redirigir si ya está logueado
  useEffect(() => {
    if (localStorage.getItem('user-session')) {
      navigate('/');
    }
  }, [navigate]);

  const passwordRequirements = useMemo(() => {
    return [
      { label: '8+ caracteres', met: password.length >= 8 },
      { label: 'Mayúscula', met: /[A-Z]/.test(password) },
      { label: 'Minúscula', met: /[a-z]/.test(password) },
      { label: 'Número', met: /[0-9]/.test(password) },
      { label: 'Símbolo', met: /[^A-Za-z0-9]/.test(password) },
    ];
  }, [password]);

  const isPasswordValid = useMemo(() => {
    return passwordRequirements.every(req => req.met);
  }, [passwordRequirements]);

  const handleRipple = (e: React.MouseEvent<HTMLButtonElement>) => {
    (window as any).createRipple?.(e);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    // Validación adicional en el lado del cliente (simulado)
    if (!isLogin && !isPasswordValid) {
      alert("La contraseña no cumple con los requisitos mínimos de seguridad.");
      return;
    }

    // Simulación de Auth
    const userData = {
      name: isLogin ? (email.split('@')[0]) : name,
      email,
      avatar: `https://i.pravatar.cc/150?u=${email}`
    };
    localStorage.setItem('user-session', JSON.stringify(userData));
    window.dispatchEvent(new Event('auth-change'));

    // Volver a donde el usuario estaba o al inicio
    const from = (location.state as any)?.from?.pathname || "/";
    navigate(from, { replace: true });
  };

  return (
    <div className="min-h-[calc(100vh-4rem)] flex items-center justify-center p-4 bg-[#0d1117]">
      <div className="w-full max-w-md bg-[#161b22] border border-[#30363d] rounded-2xl p-8 shadow-2xl relative overflow-hidden">
        {/* Decorative background element */}
        <div className="absolute top-0 right-0 -mr-16 -mt-16 w-32 h-32 bg-blue-600/10 blur-3xl rounded-full"></div>

        <div className="text-center mb-8">
          <div className="flex justify-center mb-4">
            <Logo size="lg" />
          </div>
          <h1 className="text-2xl font-bold text-white mb-2 font-sans tracking-tight">
            {isLogin ? 'Bienvenido de nuevo' : 'Crea tu cuenta'}
          </h1>
          <p className="text-slate-400 text-sm">
            {isLogin ? 'Accede a tu cuenta de SEOGrowthers' : 'Únete a la élite del SEO técnico y desarrollo'}
          </p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          {!isLogin && (
            <div>
              <label className="block text-xs font-mono text-slate-500 uppercase tracking-widest mb-2">Nombre de usuario</label>
              <input 
                type="text" 
                required
                value={name}
                onChange={(e) => setName(e.target.value)}
                placeholder="p. ej. dev_master"
                className="w-full bg-[#0d1117] border border-[#30363d] rounded-lg py-2.5 px-4 text-slate-200 focus:outline-none focus:ring-1 focus:ring-blue-500 transition-all text-sm font-sans"
              />
            </div>
          )}
          <div>
            <label className="block text-xs font-mono text-slate-500 uppercase tracking-widest mb-2">Email corporativo</label>
            <input 
              type="email" 
              required
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="nombre@empresa.com"
              className="w-full bg-[#0d1117] border border-[#30363d] rounded-lg py-2.5 px-4 text-slate-200 focus:outline-none focus:ring-1 focus:ring-blue-500 transition-all text-sm font-sans"
            />
          </div>
          <div className="relative">
            <div className="flex justify-between mb-2">
              <label className="block text-xs font-mono text-slate-500 uppercase tracking-widest">Contraseña</label>
              {isLogin && <a href="#" className="text-[10px] text-blue-500 hover:underline">¿Olvidaste tu clave?</a>}
            </div>
            <input 
              type="password" 
              required
              value={password}
              onFocus={() => !isLogin && setShowPasswordRequirements(true)}
              onBlur={() => !isLogin && password === '' && setShowPasswordRequirements(false)}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="••••••••"
              className={`w-full bg-[#0d1117] border rounded-lg py-2.5 px-4 text-slate-200 focus:outline-none focus:ring-1 transition-all text-sm font-sans ${
                !isLogin && password.length > 0 
                  ? (isPasswordValid ? 'border-emerald-500/50 focus:ring-emerald-500' : 'border-amber-500/50 focus:ring-amber-500') 
                  : 'border-[#30363d] focus:ring-blue-500'
              }`}
            />

            {/* Password Validation UI */}
            {!isLogin && showPasswordRequirements && (
              <div className="mt-3 p-3 bg-[#0d1117] border border-[#30363d] rounded-lg animate-fade-in-up">
                <p className="text-[10px] font-mono text-slate-500 uppercase tracking-wider mb-2">Requisitos de seguridad:</p>
                <div className="flex flex-wrap gap-2">
                  {passwordRequirements.map((req, idx) => (
                    <div 
                      key={idx} 
                      className={`flex items-center space-x-1.5 px-2 py-1 rounded border transition-colors ${
                        req.met 
                          ? 'bg-emerald-500/10 border-emerald-500/30 text-emerald-400' 
                          : 'bg-slate-800/50 border-slate-700 text-slate-500'
                      }`}
                    >
                      <svg className={`w-3 h-3 ${req.met ? 'opacity-100' : 'opacity-30'}`} fill="currentColor" viewBox="0 0 20 20">
                        <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
                      </svg>
                      <span className="text-[10px] font-medium">{req.label}</span>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>

          <button 
            type="submit"
            onClick={handleRipple}
            disabled={!isLogin && !isPasswordValid}
            className={`ripple-container w-full font-bold py-3 rounded-lg mt-6 transition-all shadow-lg ${
              isLogin 
                ? 'bg-blue-600 hover:bg-blue-700 text-white shadow-blue-500/10' 
                : (isPasswordValid 
                    ? 'bg-emerald-600 hover:bg-emerald-700 text-white shadow-emerald-500/10' 
                    : 'bg-slate-700 text-slate-400 cursor-not-allowed')
            }`}
          >
            {isLogin ? 'Iniciar Sesión' : 'Registrar Cuenta'}
          </button>
        </form>

        <div className="mt-8 pt-6 border-t border-[#30363d] text-center">
          <p className="text-sm text-slate-400">
            {isLogin ? '¿No tienes cuenta?' : '¿Ya eres miembro?'} {' '}
            <button 
              onClick={() => {
                setIsLogin(!isLogin);
                setPassword('');
                setShowPasswordRequirements(false);
              }}
              className="text-blue-500 hover:underline font-semibold"
            >
              {isLogin ? 'Regístrate aquí' : 'Inicia sesión'}
            </button>
          </p>
        </div>

        <div className="mt-6 flex justify-center space-x-4">
           <button className="p-2 bg-[#0d1117] border border-[#30363d] rounded-lg hover:border-slate-500 transition-colors group">
              <svg className="w-5 h-5 text-white opacity-60 group-hover:opacity-100" fill="currentColor" viewBox="0 0 24 24"><path d="M12 .297c-6.63 0-12 5.373-12 12 0 5.303 3.438 9.8 8.205 11.385.6.113.82-.258.82-.577 0-.285-.01-1.04-.015-2.04-3.338.724-4.042-1.61-4.042-1.61C4.422 18.07 3.633 17.7 3.633 17.7c-1.087-.744.084-.729.084-.729 1.205.084 1.838 1.236 1.838 1.236 1.07 1.835 2.809 1.305 3.495.998.108-.776.417-1.305.76-1.605-2.665-.3-5.466-1.332-5.466-5.93 0-1.31.465-2.38 1.235-3.22-.135-.303-.54-1.523.105-3.176 0 0 1.005-.322 3.3 1.23.96-.267 1.98-.399 3-.405 1.02.006 2.04.138 3 .405 2.28-1.552 3.285-1.23 3.285-1.23.645 1.653.24 2.873.12 3.176.765.84 1.23 1.91 1.23 3.22 0 4.61-2.805 5.625-5.475 5.92.43.372.82 1.102.82 2.222 0 1.606-.015 2.896-.015 3.286 0 .315.21.69.825.57C20.565 22.092 24 17.592 24 12.297c0-6.627-5.373-12-12-12"/></svg>
           </button>
           <button className="p-2 bg-[#0d1117] border border-[#30363d] rounded-lg hover:border-slate-500 transition-colors group">
              <svg className="w-5 h-5 text-white opacity-60 group-hover:opacity-100" fill="currentColor" viewBox="0 0 24 24"><path d="M12.48 10.92v3.28h7.84c-.24 1.84-2.21 5.39-7.84 5.39-4.84 0-8.79-4.01-8.79-8.91s3.95-8.91 8.79-8.91c2.75 0 4.59 1.16 5.64 2.16l2.58-2.48c-1.66-1.55-3.82-2.49-8.22-2.49-6.62 0-12 5.38-12 12s5.38 12 12 12c6.91 0 11.5-4.86 11.5-11.7 0-.79-.08-1.39-.18-1.98z"/></svg>
           </button>
        </div>
      </div>
    </div>
  );
};

export default Auth;

import React, { useState, useEffect } from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import Logo from './Logo';

const Navbar: React.FC = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const [user, setUser] = useState<any>(null);
  const [showUserMenu, setShowUserMenu] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(true);

  const checkAuth = () => {
    const savedUser = localStorage.getItem('user-session');
    setUser(savedUser ? JSON.parse(savedUser) : null);
  };

  useEffect(() => {
    checkAuth();

    // Initialize theme state from body class
    const isLight = document.body.classList.contains('light-mode');
    setIsDarkMode(!isLight);

    window.addEventListener('auth-change', checkAuth);
    return () => window.removeEventListener('auth-change', checkAuth);
  }, []);

  const toggleTheme = () => {
    const newDarkMode = !isDarkMode;
    setIsDarkMode(newDarkMode);
    if (newDarkMode) {
      document.body.classList.remove('light-mode');
      document.documentElement.classList.remove('light-mode');
      localStorage.setItem('theme', 'dark');
    } else {
      document.body.classList.add('light-mode');
      document.documentElement.classList.add('light-mode');
      localStorage.setItem('theme', 'light');
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('user-session');
    checkAuth();
    setShowUserMenu(false);
    navigate('/');
  };

  const navLinks = [
    { name: 'Inicio', path: '/' },
    { name: 'Noticias', path: '/news' },
    { name: 'Recursos', path: '/resources' },
    { name: 'Nosotros', path: '/about' },
    { name: 'Growth IA', path: '/ask-ai' },
  ];

  const isActive = (path: string) => location.pathname === path;

  return (
    <nav className="fixed top-0 w-full z-50 glass">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between h-16 items-center">
          <div className="flex items-center space-x-8">
            <Link to="/" className="flex items-center space-x-3 group">
              <Logo size="md" />
              <span className="text-xl font-bold text-slate-100 tracking-tight">SEOGrowthers</span>
            </Link>

            <div className="hidden md:flex space-x-6">
              {navLinks.map((link) => (
                <Link
                  key={link.path}
                  to={link.path}
                  className={`text-sm font-medium transition-colors hover:text-blue-400 ${
                    isActive(link.path) ? 'text-blue-500' : 'text-slate-400'
                  }`}
                >
                  {link.name}
                </Link>
              ))}
            </div>
          </div>

          <div className="flex items-center space-x-4">
            <div className="relative hidden lg:block">
              <input 
                type="text" 
                placeholder="Buscar tácticas SEO..." 
                className="bg-[#010409] border border-[#30363d] rounded-md py-1 px-3 text-sm focus:outline-none focus:ring-1 focus:ring-blue-500 w-64 transition-all"
              />
              <kbd className="absolute right-2 top-1.5 px-1.5 py-0.5 text-[10px] font-mono text-slate-500 bg-[#161b22] border border-[#30363d] rounded">/</kbd>
            </div>

            {/* Theme Toggle Button */}
            <button 
              onClick={toggleTheme}
              className="p-2 rounded-md hover:bg-blue-500/10 transition-colors text-slate-400 hover:text-blue-400"
              title={isDarkMode ? "Cambiar a modo claro" : "Cambiar a modo oscuro"}
            >
              {isDarkMode ? (
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364-6.364l-.707.707M6.343 17.657l-.707.707M17.657 17.657l-.707-.707M6.343 6.343l-.707-.707M12 5a7 7 0 100 14 7 7 0 000-14z" />
                </svg>
              ) : (
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z" />
                </svg>
              )}
            </button>

            {user ? (
              <div className="relative">
                <button 
                  onClick={() => setShowUserMenu(!showUserMenu)}
                  className="flex items-center space-x-2 bg-[#161b22] border border-[#30363d] rounded-md py-1 px-2 hover:border-[#8b949e] transition-all"
                >
                  <img src={user.avatar} className="w-6 h-6 rounded-full" alt="User" />
                  <span className="text-xs font-semibold text-white hidden sm:inline">{user.name}</span>
                  <svg className="w-4 h-4 text-slate-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
                  </svg>
                </button>
                {showUserMenu && (
                  <div className="absolute right-0 mt-2 w-48 bg-[#161b22] border border-[#30363d] rounded-md shadow-xl py-1 z-50">
                    <div className="px-4 py-2 border-b border-[#30363d] mb-1">
