);

const NewsDetail: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const location = useLocation();
  const [news, setNews] = useState<NewsItem | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [showCopied, setShowCopied] = useState(false);
  const [showScrollTop, setShowScrollTop] = useState(false);
  const [isUserLoggedIn, setIsUserLoggedIn] = useState(false);
  const [currentUser, setCurrentUser] = useState<any>(null);

  const [comments, setComments] = useState<Comment[]>([
    { id: 'c1', user: 'TechEnthusiast', text: 'Excelente análisis. Esto cambia por completo las reglas del juego. **NVIDIA** está en otro nivel.', date: 'Hace 2 horas' },
    { id: 'c2', user: 'DevMaster', text: 'Me preocupa la eficiencia térmica de estos nuevos chips, pero el rendimiento es innegable. Aquí hay un fragmento de lo que espero:\n\n`performance_gain = (new_core_count * clock_speed) / current_arch` \n\n¿Qué opinan?', date: 'Hace 5 horas' }
  ]);
  const [newComment, setNewComment] = useState('');

  const updateMetaTags = (item: NewsItem) => {
    // Título dinámico
    document.title = `${item.title} | SEOGrowthers`;

    // Meta Descripción
    let metaDescription = document.querySelector('meta[name="description"]');
    if (!metaDescription) {
      metaDescription = document.createElement('meta');
      metaDescription.setAttribute('name', 'description');
      document.head.appendChild(metaDescription);
    }
    metaDescription.setAttribute('content', item.excerpt);

    // Meta Palabras Clave (Keywords)
    let metaKeywords = document.querySelector('meta[name="keywords"]');
    if (!metaKeywords) {
      metaKeywords = document.createElement('meta');
      metaKeywords.setAttribute('name', 'keywords');
      document.head.appendChild(metaKeywords);
    }
    const keywords = [
      item.category,
      'Tecnología',
      'Inteligencia Artificial',
      'Programación',
      'SEO Técnico',
      item.author,
      'Growth Hacking'
    ].join(', ');
    metaKeywords.setAttribute('content', keywords);

    // Open Graph para redes sociales (Extra de calidad)
    const ogTitle = document.querySelector('meta[property="og:title"]') || document.createElement('meta');
    if (!ogTitle.parentNode) { ogTitle.setAttribute('property', 'og:title'); document.head.appendChild(ogTitle); }
    ogTitle.setAttribute('content', item.title);

    const ogDesc = document.querySelector('meta[property="og:description"]') || document.createElement('meta');
    if (!ogDesc.parentNode) { ogDesc.setAttribute('property', 'og:description'); document.head.appendChild(ogDesc); }
    ogDesc.setAttribute('content', item.excerpt);

    const ogImg = document.querySelector('meta[property="og:image"]') || document.createElement('meta');
    if (!ogImg.parentNode) { ogImg.setAttribute('property', 'og:image'); document.head.appendChild(ogImg); }
    ogImg.setAttribute('content', item.imageUrl);
  };

  useEffect(() => {
    // Verificar sesión
    const savedUser = localStorage.getItem('user-session');
    if (savedUser) {
      setIsUserLoggedIn(true);
      setCurrentUser(JSON.parse(savedUser));
    }

    setIsLoading(true);
    const found = ALL_NEWS.find(n => n.id === id);

    const timer = setTimeout(() => {
      if (found) {
        setNews(found);
        updateMetaTags(found);
      }
      setIsLoading(false);
    }, 600);

    window.scrollTo(0, 0);

    const handleScroll = () => {
      setShowScrollTop(window.scrollY > 400);
    };

    window.addEventListener('scroll', handleScroll);
    return () => {
      window.removeEventListener('scroll', handleScroll);
      clearTimeout(timer);
      // Reset title when leaving
      document.title = 'SEOGrowthers | Tech, AI & Growth';
    };
  }, [id]);

  const relatedNews = useMemo(() => {
    if (!news) return [];
    return ALL_NEWS
      .filter(n => n.category === news.category && n.id !== news.id)
      .slice(0, 3);
  }, [news]);

  const handleShare = async () => {
    if (!news) return;
    try {
      await navigator.clipboard.writeText(window.location.href);
      setShowCopied(true);
      setTimeout(() => setShowCopied(false), 2000);
    } catch (err) {
      console.error('Failed to copy:', err);
    }
  };

  const handleScrollToTop = () => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleAddComment = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newComment.trim() || !currentUser) return;
    const comment: Comment = {
      id: Date.now().toString(),
      user: currentUser.name,
      text: newComment,
      date: 'Justo ahora'
    };
    setComments([comment, ...comments]);
    setNewComment('');
  };

  if (isLoading) {
    return (
      <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-12 relative">
        <NewsDetailSkeleton />
      </div>
    );
  }

  if (!news) {
    return (
      <div className="max-w-7xl mx-auto px-4 py-20 text-center">
        <h2 className="text-2xl font-bold text-white mb-4">Noticia no encontrada</h2>
        <Link to="/news" className="text-blue-400 hover:underline">Volver al archivo</Link>
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-12 relative">
      <Link to="/news" className="inline-flex items-center text-sm text-slate-400 hover:text-blue-400 mb-8 transition-colors">
        <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 mr-2" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" />
        </svg>
        Volver a noticias
      </Link>

      <header className="mb-8">
        <div className="flex items-center space-x-2 mb-4">
          <span className="px-2 py-1 text-[10px] font-bold bg-blue-600/20 text-blue-400 border border-blue-500/30 rounded uppercase tracking-wider">
            {news.category}
          </span>
          <span className="text-slate-500 text-xs">•</span>
          <span className="text-slate-500 text-xs">{news.date}</span>
        </div>
        <h1 className="text-4xl md:text-5xl font-extrabold text-white leading-tight mb-6">
          {news.title}
        </h1>

        <div className="flex flex-wrap items-center justify-between gap-6 mb-8 pb-8 border-b border-slate-800">
          <div className="flex items-center space-x-3">
            <div className="w-10 h-10 rounded-full bg-slate-800 border border-slate-700 flex items-center justify-center text-slate-300 font-bold">
              {news.author.charAt(0)}
            </div>
            <div>
              <p className="text-sm font-semibold text-slate-200">{news.author}</p>
              <p className="text-xs text-slate-500">Editor en SEOGrowthers</p>
            </div>
          </div>

          <div className="flex items-center space-x-3">
            {showCopied && (
              <span className="text-[10px] font-mono text-green-400 animate-pulse">¡Enlace copiado!</span>
            )}
            <button 
              onClick={handleShare}
              className="inline-flex items-center space-x-2 px-4 py-2 rounded-lg bg-[#161b22] border border-[#30363d] text-slate-300 text-xs font-bold hover:bg-[#1f242c] hover:border-[#8b949e] hover:text-white transition-all shadow-sm"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z" />
              </svg>
              <span>Compartir</span>
            </button>
          </div>
        </div>
      </header>

      <div className="mb-12 rounded-2xl overflow-hidden border border-slate-800 shadow-2xl">
        <img src={news.imageUrl} alt={news.title} className="w-full h-auto object-cover max-h-[500px]" />
      </div>

      <article className="prose prose-invert max-w-none mb-16">
        <p className="text-xl text-slate-300 leading-relaxed font-medium italic border-l-4 border-blue-500 pl-6 mb-8">
          {news.excerpt}
        </p>
        <div className="text-slate-300 text-lg leading-loose space-y-6">
          {news.content?.split('\n\n').map((paragraph, idx) => (
            <p key={idx}>{paragraph}</p>
          ))}
        </div>
      </article>

      {/* Related News Section */}
      {relatedNews.length > 0 && (
        <section className="py-12 border-t border-slate-800">
          <h3 className="text-2xl font-bold text-white mb-8">Noticias Relacionadas</h3>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            {relatedNews.map(item => (
              <div key={item.id} className="scale-90 origin-top-left -mr-[11%]">
                <NewsCard news={item} />
              </div>
            ))}
          </div>
        </section>
      )}

      {/* Comments Section */}
      <section className="pt-12 border-t border-slate-800">
        <div className="flex items-center justify-between mb-8">
          <h3 className="text-2xl font-bold text-white flex items-center">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 mr-3 text-blue-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" />
            </svg>
            Comentarios ({comments.length})
          </h3>
        </div>

        {/* Auth Restricted Form */}
        {isUserLoggedIn ? (
          <form onSubmit={handleAddComment} className="mb-12 animate-fade-in">
            <div className="relative">
              <textarea
                value={newComment}
                onChange={(e) => setNewComment(e.target.value)}
                placeholder={`Como ${currentUser.name}, ¿qué opinas de esto?`}
                className="w-full bg-[#0d1117] border border-slate-800 rounded-xl p-4 text-slate-200 focus:outline-none focus:ring-1 focus:ring-blue-500 transition-all mb-4 h-32 text-sm leading-relaxed"
              />
            </div>
            <button
              type="submit"
              disabled={!newComment.trim()}
              className="bg-blue-600 hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed text-white font-semibold py-2 px-6 rounded-lg transition-all text-sm shadow-lg shadow-blue-500/10"
            >
              Publicar comentario
            </button>
          </form>
        ) : (
          <div className="mb-12 p-8 bg-[#161b22] border border-dashed border-[#30363d] rounded-2xl text-center group">
            <div className="inline-flex items-center justify-center w-12 h-12 rounded-full bg-slate-800 mb-4 group-hover:scale-110 transition-transform">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-slate-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" />
              </svg>
            </div>
            <h4 className="text-white font-bold mb-2">Únete a la discusión técnica</h4>
            <p className="text-sm text-slate-400 mb-6 max-w-sm mx-auto">
              Solo los miembros de SEOGrowthers pueden publicar comentarios. Regístrate para compartir tus insights.
            </p>
            <Link 
              to="/login" 
              state={{ from: location }}
              className="inline-block bg-white text-[#0d1117] font-bold py-2 px-6 rounded-lg hover:bg-blue-50 transition-colors"
            >
              Iniciar sesión / Registro
            </Link>
          </div>
        )}

        <div className="space-y-8">
          {comments.map(comment => (
            <div key={comment.id} className="flex space-x-4 animate-fade-in group">
              <div className="w-10 h-10 rounded-full bg-slate-800 border border-slate-700 flex items-center justify-center text-xs font-bold text-slate-400 flex-shrink-0">
                {comment.user.charAt(0)}
              </div>
              <div className="flex-grow">
                <div className="flex items-center space-x-2 mb-2">
                  <span className="text-sm font-bold text-slate-200 group-hover:text-blue-400 transition-colors">{comment.user}</span>
                  <span className="text-[10px] text-slate-500 font-mono">• {comment.date}</span>
                </div>
                <div 
                  className="comment-content prose prose-sm prose-invert max-w-none text-slate-400 bg-[#161b22] border border-slate-800/50 rounded-xl p-4 leading-relaxed"
                  dangerouslySetInnerHTML={{ __html: marked.parse(comment.text) }}
                />
              </div>
            </div>
          ))}
        </div>
      </section>

      <button
        onClick={handleScrollToTop}
        className={`fixed bottom-8 right-8 z-50 p-3 rounded-full bg-[#161b22] border border-[#30363d] text-slate-400 hover:text-blue-400 hover:border-blue-500/50 hover:bg-[#1f242c] transition-all duration-300 shadow-2xl ${
          showScrollTop ? 'translate-y-0 opacity-100' : 'translate-y-12 opacity-0 pointer-events-none'
        }`}
      >
        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 10l7-7m0 0l7 7m-7-7v18" />
        </svg>
      </button>
    </div>
  );
};

