import React, { useState, useRef, useEffect } from 'react';
import { askDevAssistant } from '../services/geminiService';
import { ChatMessage } from '../types';
import Logo from '../components/Logo';

const AIChat: React.FC = () => {
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'assistant', content: '¡Hola! Soy el asistente inteligente de SEOGrowthers. ¿Quieres optimizar tu web, depurar código o conocer lo último en IA aplicada al crecimiento orgánico?' }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleRipple = (e: React.MouseEvent<HTMLButtonElement>) => {
    (window as any).createRipple?.(e);
  };

  const handleSend = async (e?: React.MouseEvent<HTMLButtonElement>) => {
    if (!input.trim() || isLoading) return;
    if (e) handleRipple(e);

    const userMsg: ChatMessage = { role: 'user', content: input };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsLoading(true);

    const response = await askDevAssistant(input, messages);

    setMessages(prev => [...prev, { role: 'assistant', content: response || 'Sin respuesta.' }]);
    setIsLoading(false);
  };

  return (
    <div className="max-w-4xl mx-auto px-4 sm:px-6 py-12 flex flex-col h-[calc(100vh-8rem)]">
      <div className="flex-shrink-0 mb-6 text-center">
        <div className="flex justify-center mb-4">
          <Logo size="lg" />
        </div>
        <h1 className="text-3xl font-bold text-white mb-2">Growth Assistant</h1>
        <p className="text-slate-400 text-sm">Estrategias SEO, IA y Desarrollo Web.</p>
      </div>

      <div 
        ref={scrollRef}
        className="flex-grow overflow-y-auto bg-[#0d1117] border border-[#30363d] rounded-t-2xl p-6 space-y-6 scroll-smooth shadow-inner"
      >
        {messages.map((msg, idx) => (
          <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-fade-in-up`}>
            <div className={`max-w-[85%] rounded-2xl px-5 py-4 shadow-sm ${
              msg.role === 'user' 
                ? 'bg-blue-600 text-white rounded-tr-none' 
                : 'bg-[#161b22] text-slate-200 border border-[#30363d] rounded-tl-none'
            }`}>
              <div className="text-sm leading-relaxed whitespace-pre-wrap font-sans">
                {msg.content}
              </div>
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex justify-start animate-pulse">
            <div className="bg-[#161b22] border border-[#30363d] rounded-2xl rounded-tl-none px-5 py-4">
              <div className="flex space-x-2">
                <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce" style={{ animationDelay: '0s' }}></div>
                <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce" style={{ animationDelay: '0.2s' }}></div>
                <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce" style={{ animationDelay: '0.4s' }}></div>
              </div>
            </div>
          </div>
        )}
      </div>

      <div className="flex-shrink-0 bg-[#161b22] border-x border-b border-[#30363d] rounded-b-2xl p-4 shadow-lg">
        <div className="relative flex items-center">
          <input 
            type="text" 
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && handleSend()}
            placeholder="Escribe tu consulta técnica aquí..."
            className="w-full bg-[#010409] border border-[#30363d] rounded-xl py-4 px-5 pr-14 text-slate-200 focus:outline-none focus:ring-2 focus:ring-blue-500/40 transition-all placeholder-slate-500 shadow-sm"
          />
          <button 
            onClick={(e) => handleSend(e)}
            disabled={isLoading || !input.trim()}
            className="ripple-container absolute right-3 p-2 bg-blue-600 hover:bg-blue-700 text-white disabled:bg-slate-700 disabled:opacity-50 transition-all rounded-lg shadow-md"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" />
            </svg>
          </button>
        </div>
        <p className="text-[10px] text-slate-500 mt-3 text-center font-mono tracking-widest uppercase opacity-70">
          SEOGrowthers Intelligent Engine
        </p>
      </div>
    </div>
  );
};

