interface NewsCardProps {
  news: NewsItem;
}

const NewsCard: React.FC<NewsCardProps> = ({ news }) => {
  const [isVisible, setIsVisible] = useState(false);
  const cardRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
          observer.unobserve(entry.target);
        }
      },
      { threshold: 0.1 }
    );

    if (cardRef.current) {
      observer.observe(cardRef.current);
    }

    return () => {
      if (cardRef.current) {
        observer.unobserve(cardRef.current);
      }
    };
  }, []);

  const getCategoryColor = (category: string) => {
    switch (category) {
      case 'AI': return 'bg-purple-900/40 text-purple-300 border-purple-500/30';
      case 'Dev': return 'bg-blue-900/40 text-blue-300 border-blue-500/30';
      case 'Tech': return 'bg-green-900/40 text-green-300 border-green-500/30';
      default: return 'bg-slate-800 text-slate-300 border-slate-600/30';
    }
  };

  return (
    <Link to={`/news/${news.id}`} className="group h-full block">
      <div 
        ref={cardRef}
        className="bg-[#0d1117] border border-[#30363d] rounded-xl overflow-hidden hover:border-[#8b949e] transition-all duration-300 flex flex-col h-full shadow-lg hover:shadow-blue-500/10 active:scale-[0.98]"
      >
        {/* Image Container */}
        <div className="relative h-52 overflow-hidden border-b border-[#30363d] bg-slate-900">
          {/* Subtle Glow Overlay */}
          <div className="absolute inset-0 z-10 bg-gradient-to-t from-[#0d1117]/80 via-transparent to-transparent opacity-60 group-hover:opacity-40 transition-opacity" />

          <img 
            src={news.imageUrl} 
            alt={news.title} 
            className={`w-full h-full object-cover transition-all duration-[1200ms] ease-out group-hover:scale-105 group-hover:brightness-110 group-hover:contrast-[1.05] ${
              isVisible ? 'opacity-100 translate-y-0 scale-100' : 'opacity-0 translate-y-4 scale-110 blur-sm'
            }`}
          />

          {/* Top Tag */}
          <div className="absolute top-4 left-4 z-20">
            <span className={`text-[10px] font-bold px-2.5 py-1 rounded-md border backdrop-blur-md uppercase tracking-wider shadow-sm ${getCategoryColor(news.category)}`}>
              {news.category}
            </span>
          </div>

          {/* Hover Shine Effect - Enhanced */}
          <div className="absolute inset-0 z-15 opacity-0 group-hover:opacity-100 transition-opacity duration-700 pointer-events-none bg-gradient-to-r from-transparent via-white/10 to-transparent skew-x-[-20deg] transform -translate-x-full group-hover:translate-x-[150%] transition-transform duration-1000 ease-in-out" />
        </div>

        {/* Content Section */}
        <div className="p-6 flex flex-col flex-grow bg-gradient-to-b from-[#161b22] to-[#0d1117]">
          <h3 className="text-lg font-bold text-slate-100 group-hover:text-blue-400 transition-colors leading-snug mb-3">
            {news.title}
          </h3>
          <p className="text-sm text-slate-400 line-clamp-2 mb-5 flex-grow leading-relaxed">
            {news.excerpt}
          </p>

          <div className="flex items-center justify-between mt-auto pt-4 border-t border-[#30363d]/50">
            <div className="flex items-center space-x-2">
              <div className="w-6 h-6 rounded-full bg-blue-600/20 border border-blue-500/30 flex items-center justify-center text-[10px] font-bold text-blue-400">
                {news.author.charAt(0)}
              </div>
              <span className="text-xs text-slate-300 font-medium">{news.author}</span>
            </div>
            <div className="flex items-center text-xs text-slate-500 font-mono">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3 mr-1 opacity-70" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" />
              </svg>
              {news.date}
