      const matchesType = activeType === 'Todos' || res.type === activeType;
      const matchesDiff = activeDiff === 'Todos' || 
        (activeDiff === 'Principiante' && res.difficulty === 'Beginner') ||
        (activeDiff === 'Intermedio' && res.difficulty === 'Intermediate') ||
        (activeDiff === 'Avanzado' && res.difficulty === 'Advanced');

      const searchLower = searchTerm.toLowerCase();
      const matchesSearch = searchTerm === '' || 
        res.title.toLowerCase().includes(searchLower) ||
        res.description.toLowerCase().includes(searchLower) ||
        res.tags.some(tag => tag.toLowerCase().includes(searchLower));

      return matchesType && matchesDiff && matchesSearch;
    });
  }, [activeType, activeDiff, searchTerm]);

