                )}
              </div>
            ) : (
              <Link 
                to="/login"
                className="bg-blue-600 hover:bg-blue-700 text-white text-xs font-bold py-2 px-5 rounded-lg transition-all shadow-md shadow-blue-500/10"
              >
                Acceder
              </Link>
            )}
          </div>
        </div>
      </div>
    </nav>
  );
};

